describe('plain paths', () => {
  const profile = {
    values: [{ code: '' }, { code: 'VIRT-1' }],
    cards: [{ code: 'A', n: 1 }, { code: 'B', n: 2 }],
    physical: null,
    virtual: 'V',
  };
  it('the value itself, a row by index, a row by field', () => {
    expect(read(profile, '.')).toBe(profile);
    expect(read(profile, 'cards[1].n')).toBe(2);
    expect(read(profile, 'cards[code=B].n')).toBe(2);
    expect(read(profile, 'cards[code=Z].n')).toBeUndefined();
    expect(read(profile, 'missing.deeper')).toBeUndefined();
  });
  it('[*] is the first row holding a value; ?? the first path holding one', () => {
    expect(read(profile, 'values[*].code')).toBe('VIRT-1');
    expect(read(profile, 'physical ?? virtual')).toBe('V');
    expect(read(profile, 'physical ?? nothing')).toBeUndefined();
  });
  it('sumfx adds each row at its currency rate and leaves unrated rows out', () => {
    const wallets = { data: [{ a: 100, c: 'AED' }, { a: 10, c: 'usd' }, { a: 5, c: 'EUR' }] };
    expect(read(wallets, 'sumfx(data;a;c;AED=1,USD=3.5)')).toBe(135);
    expect(read(wallets, 'sumfx(data;a;c;AED=1)')).toBe(100);
  });
});

describe('group(…): one entry per value of a field', () => {
  const wallets = {
    data: [
      { walletName: 'Operating', currencyCode: 'AED', currentBalance: 600, type: 'CURRENT' },
      { walletName: 'Escrow', currencyCode: 'AED', currentBalance: 300, type: 'ESCROW' },
      { walletName: 'Payroll', currencyCode: 'AED', currentBalance: 100, type: 'CURRENT' },
      { walletName: 'USD Trade', currencyCode: 'USD', currentBalance: '2,500.00', type: 'CURRENT' },
      { walletName: 'Overdrawn', currencyCode: 'AED', currentBalance: -50 },
      { walletName: 'No currency', currentBalance: 10 },
    ],
  };
  it('adds up each currency, counts its accounts, largest first', () => {
    expect(read(wallets, 'group(data;currencyCode;currentBalance)')).toEqual([
      { key: 'USD', label: 'USD', total: 2500, count: 1 },
      { key: 'AED', label: 'AED', total: 950, count: 4 },
    ].map((g) => ({ ...g, share: expect.any(Number), legend: expect.any(String), sum: '3,450.00' })));
  });
  it('a row with no key is left out, unless blank= names it', () => {
    expect(read<unknown[]>(wallets, 'group(data;type;currentBalance)')).toHaveLength(2);
    expect(read(wallets, 'group(data;type;currentBalance;blank=Unspecified).key')).toEqual(['CURRENT', 'ESCROW', 'Unspecified']);
  });
  it('an empty filter value keeps the largest group', () => {
    expect(read(wallets, 'group(data;walletName;currentBalance;currencyCode=;positive).key')).toEqual(['USD Trade']);
    expect(read(wallets, 'group(data;walletName;currentBalance;currencyCode=AED;positive).total')).toEqual([600, 300, 100]);
  });
  it('positive leaves out an overdrawn account; share is of the positive whole', () => {
    expect(read<Entry[]>(wallets, 'group(data;walletName;currentBalance;currencyCode=AED;positive)').map((g) => g.share)).toEqual([60, 30, 10]);
  });
  it('top=n folds the rest into "Other"', () => {
    expect(read(wallets, 'group(data;walletName;currentBalance;currencyCode=AED;positive;top=1)')).toEqual([
      { key: 'Operating', label: 'Operating', total: 600, count: 1, share: 60, legend: 'Operating · 60%', sum: '1,000.00' },
      { key: 'Other', label: 'Other', total: 400, count: 2, share: 40, legend: 'Other · 40%', sum: '1,000.00' },
    ]);
  });
  it('one entry and one field, and an absent entry', () => {
    expect(read(wallets, 'group(data;currencyCode;currentBalance)[1].key')).toBe('AED');
    expect(read(wallets, 'group(data;currencyCode;currentBalance)[2].key')).toBeUndefined();
  });
  it('an unanswered call is no rows, not an error', () => {
    expect(read(undefined, 'group(data;currencyCode;currentBalance)')).toEqual([]);
  });
  it('a bare option keeps rows holding the field; ! the rows without', () => {
    const rows = { records: [{ c: 'AED', a: 5, id: 'x' }, { c: 'AED', a: 7 }] };
    expect(read(rows, 'group(records;c;a;id)[0].total')).toBe(5);
    expect(read(rows, 'group(records;c;a;!id)[0].total')).toBe(7);
  });
  it('a comparison narrows the rows before the largest value is chosen', () => {
    const now = new Date().toISOString();
    const tx = { records: [{ c: 'USD', a: 500, at: '2001-01-01' }, { c: 'AED', a: 5, at: now }, { c: 'AED', a: 7, at: now }] };
    expect(read(tx, 'group(records;c;a;c=)[0].key')).toBe('USD');
    expect(read(tx, 'group(records;c;a;at>=months:6;c=)[0].key')).toBe('AED');
    expect(read<number[]>(tx, 'months(records;at;a;6;at>=months:6;c=).total').at(-1)).toBe(12);
  });
  it('whole=100;rest= adds what the register does not account for', () => {
    const owns = { records: [{ s: 'A', p: '60' }, { s: 'B', p: '30' }] };
    expect(read<Entry[]>(owns, 'group(records;s;p;whole=100;rest=Not recorded)').map((g) => [g.key, g.total]))
      .toEqual([['A', 60], ['B', 30], ['Not recorded', 10]]);
    expect(read({ records: [{ s: 'A', p: '100' }] }, 'group(records;s;p;whole=100;rest=Not recorded).length')).toBe(1);
  });
  it('unit= puts the figure in the legend; unit=@field reads it from the rows', () => {
    const acc = { records: [{ k: 'Operating', b: 1234.5, c: 'AED' }, { k: 'Escrow', b: 1000, c: 'AED' }, { k: 'Dollar', b: 5, c: 'USD' }] };
    expect(read({ records: acc.records.slice(0, 2) }, 'group(records;k;b;unit=AED).legend'))
      .toEqual(['Operating · AED 1,234.50 · 55%', 'Escrow · AED 1,000.00 · 45%']);
    expect(read(acc, 'group(records;k;b;c=;unit=@c)[0].legend')).toBe('Operating · AED 1,234.50 · 55%');
    expect(read(acc, 'group(records;k;b;c=;unit=@c)[0].sum')).toBe('AED 2,234.50');
  });
});

