describe('tree and split', () => {
  const data = {
    from: [
      { id: 'h', legalName: 'Modon Holding' }, { id: 'a', legalName: 'Alpha SPV' }, { id: 'b', legalName: 'Beta SPV' }, { id: 'c', legalName: 'Gamma' },
    ],
    records: [
      { relationshipType: 'OWNS', sourceType: 'LEGAL_ENTITY', sourceId: 'h', targetId: 'a', ownershipPercentage: '100' },
      { relationshipType: 'OWNS', sourceType: 'LEGAL_ENTITY', sourceId: 'h', targetId: 'b', ownershipPercentage: '70' },
      { relationshipType: 'OWNS', sourceType: 'LEGAL_ENTITY', sourceId: 'a', targetId: 'b', ownershipPercentage: '30' },
      { relationshipType: 'DIRECTOR_OF', sourceType: 'NATURAL_PERSON', sourceId: 'p', targetId: 'a' },
    ],
  };
  it('parents before children, siblings by name, placed under the largest holder', () => {
    const t = read<TreeRow[]>(data, 'tree(from;id;legalName;records;sourceId;targetId;relationshipType=OWNS;pct=ownershipPercentage)');
    expect(t.map((r) => [r.id, r.depth, r.parentPct, r.alsoHeldBy])).toEqual([
      ['c', 0, '', ''], ['h', 0, '', ''], ['a', 1, '100', ''], ['b', 1, '70', 'Alpha SPV 30%'],
    ]);
  });
  it('root= puts one row on top of everything without a parent', () => {
    const t = read<TreeRow[]>(data, 'tree(from;id;legalName;records;sourceId;targetId;relationshipType=OWNS;root=Modon Group)');
    expect(t.map((r) => [r.id, r.depth])).toEqual([['__root', 0], ['c', 1], ['h', 1], ['a', 2], ['b', 2]]);
    expect(t[0]?.legalName).toBe('Modon Group');
  });
  it('a grouped read may start from another', () => {
    expect(ids(data, 'rows(tree(from;id;legalName;records;sourceId;targetId;relationshipType=OWNS);!parentId)')).toEqual(['c', 'h']);
    expect(read({ r: [{ n: 'Modon (Holding)' }, { n: 'x' }] }, 'rows(r;n=Modon (Holding)).length')).toBe(1);
  });
  it('split: a text into entries', () => {
    expect(read({ roles: 'corporate:viewer  corporate:initiator' }, 'split(roles).key')).toEqual(['corporate:viewer', 'corporate:initiator']);
  });
});

describe('gathering', () => {
  it('pages stop on a short page and on the count', async () => {
    const asked: number[] = [];
    const call = async (v: Record<string, unknown>) => {
      const n = Number(v.pageNumber);
      asked.push(n);
      return { count: 450, records: Array.from({ length: n < 2 ? 200 : 50 }, (_, i) => ({ i: n * 200 + i })) };
    };
    const out = (await gatherPages(call, { pageSize: 200 }, { max: 10, pageParam: 'pageNumber', recordsPath: 'records', countPath: 'count' }, '')) as { records: unknown[]; count: number };
    expect(asked).toEqual([0, 1, 2]);
    expect(out.records).toHaveLength(450);
    expect(out.count).toBe(450);
  });
  it('pages stop once the last row is older than the window', async () => {
    const asked: number[] = [];
    const call = async (v: Record<string, unknown>) => {
      asked.push(Number(v.pageNumber));
      const at = v.pageNumber === 0 ? '2099-01-01' : '2000-01-01';
      return { records: [{ at }, { at }] };
    };
    await gatherPages(call, { pageSize: 2 }, { max: 10, pageParam: 'pageNumber', recordsPath: 'records', countPath: 'count', untilPath: 'at' }, 'days:30');
    expect(asked).toEqual([0, 1]);
  });
  it('each: a failed call costs only its own rows', async () => {
    const call = async (v: Record<string, unknown>) => {
      if (v.id === 'b') throw new Error('403');
      return { records: [{ r: v.id }] };
    };
    const out = (await gatherEach(call, {}, 'id', ['a', 'b', 'c'])) as { records: unknown[] };
    expect(out.records).toEqual([{ r: 'a', __from: 'a' }, { r: 'c', __from: 'c' }]);
  });
  it('the keys a repeated read asks for: each once, at most max', () => {
    const src = { records: [{ id: 'a' }, { id: 'b' }, { id: 'a' }, { id: '' }] };
    expect(gatherKeys(src, 'records', 'id', 40)).toEqual(['a', 'b']);
    expect(gatherKeys(src, 'records', 'id', 1)).toEqual(['a']);
    expect(gatherKeys(undefined, 'records', 'id', 40)).toEqual([]);
    expect(gatherSource(src, 'records')).toHaveLength(4);
    expect(gatherSource(undefined, 'records')).toEqual([]);
  });
  it('answers are added only to an answer that is an object', () => {
    expect(withAnswers({ a: 1 }, { b: 2 })).toEqual({ a: 1, b: 2 });
    expect(withAnswers([1], { b: 2 })).toEqual([1]);
    expect(withAnswers(undefined, { b: 2 })).toBeUndefined();
  });
});

describe('format ops', () => {
  it('day: the ISO calendar day, never moved into another zone', () => {
    expect(fmt('2026-10-05T23:30:00-05:00', [['day']])).toBe('05 Oct 2026');
    expect(fmt('2026-03-01', [['day']])).toBe('01 Mar 2026');
    expect(fmt('n/a', [['day']])).toBe('n/a');
  });
  it('daytime: UTC, 24-hour', () => {
    expect(fmt('2026-10-05T14:05:00Z', [['daytime']])).toBe('05 Oct 2026, 14:05');
  });
  it('pct: two decimals at most, "<0.01" for a holding too small to show', () => {
    expect(fmt('92.5000', [['pct']])).toBe('92.5');
    expect(fmt('0.001', [['pct']])).toBe('<0.01');
    expect(fmt('0', [['pct']])).toBe('0');
  });
  it('joined, bars and compact', () => {
    expect(fmt('Mashreq', [['joined', '·']])).toBe(' · Mashreq');
    expect(fmt('', [['joined', '·']])).toBe('');
    expect(fmt('a, b,c', [['bars']])).toBe('a|b|c');
    expect(fmt(' AE07 0331 2345 ', [['compact'], ['upper']])).toBe('AE0703312345');
  });
});
